cd "C:/Users/ryanf/AppData/Local/Temp/pixl caller review 249faf48d4f549729dad6842462c74ce/consumer" && python -B -I - <<'EOF'
import hashlib, os
snap = {}
for line in open("work/rev14-protected-snapshot.sha256", encoding="utf-8"):
    h, p = line.rstrip("\n").split("  ", 1)
    snap[p] = h
kit_snap = {p: h for p, h in snap.items() if p.startswith("pixl-kit/") and "__pycache__" not in p}
now = {}
for dp, dn, fn in os.walk("pixl-kit"):
    for f in fn:
        p = os.path.join(dp, f).replace("\\", "/")
        now[p] = hashlib.sha256(open(p, "rb").read()).hexdigest()
print("kit entries in rev14 snapshot:", len(kit_snap), " kit files now:", len(now))
print("CHANGED:")
for p in sorted(kit_snap):
    if p in now and now[p] != kit_snap[p]:
        print("  ", p, kit_snap[p][:16], "->", now[p][:16])
print("NEW:")
for p in sorted(set(now) - set(kit_snap)):
    print("  ", p, now[p])
print("GONE:")
for p in sorted(set(kit_snap) - set(now)):
    print("  ", p)
print("--- head of snapshot file:")
print(open("work/rev14-protected-snapshot.sha256", encoding="utf-8").read()[:400])
print("--- non-kit snapshot entries:", sum(1 for p in snap if not p.startswith("pixl-kit/")))
EOF

